import{_ as s,a0 as p,w as l,s as u,ao as r,I as a,x as o,a1 as n,A as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"在 Ubuntu 14.04/15.04 上配置 Node JS v4.0.0 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 14.04/15.04 上配置 Node JS v4.0.0 | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 14.04/15.04 上配置 Node JS v4.0.0 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 14.04/15.04 上配置 Node JS v4.0.0 | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20150914 How to Setup Node JS v4.0.0 on Ubuntu 14.04 or 15.04","title":"在 Ubuntu 14.04/15.04 上配置 Node JS v4.0.0","tag":"201510","desc":""},"relativePath":"201510/20150914 How to Setup Node JS v4.0.0 on Ubuntu 14.04 or 15.04.md","filePath":"[post].md"}'),i={name:"201510/20150914 How to Setup Node JS v4.0.0 on Ubuntu 14.04 or 15.04.md"};function b(m,e,h,g,N,c){const t=p("Link");return l(),u("div",null,[e[16]||(e[16]=r(`<h1 id="在-ubuntu-14-04-15-04-上配置-node-js-v4-0-0" tabindex="-1">在 Ubuntu 14.04/15.04 上配置 Node JS v4.0.0 <a class="header-anchor" href="#在-ubuntu-14-04-15-04-上配置-node-js-v4-0-0" aria-label="Permalink to “在 Ubuntu 14.04/15.04 上配置 Node JS v4.0.0”">​</a></h1><p>大家好，Node.JS 4.0 发布了，这个流行的服务器端 JS 平台合并了 Node.js 和 io.js 的代码，4.0 版就是这两个项目结合的产物——现在合并为一个代码库。这次最主要的变化是 Node.js 封装了4.5 版本的 Google V8 JS 引擎，与当前的 Chrome 所带的一致。所以，紧跟 V8 的发布可以让 Node.js 运行的更快、更安全，同时更好的利用 ES6 的很多语言特性。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/nodejs.png" alt="Node JS"></p><p>Node.js 4.0 发布的主要目标是为 io.js 用户提供一个简单的升级途径，所以这次并没有太多重要的 API 变更。下面的内容让我们来看看如何轻松的在 ubuntu server 上安装、配置 Node.js。</p><h3 id="基础系统安装" tabindex="-1">基础系统安装 <a class="header-anchor" href="#基础系统安装" aria-label="Permalink to “基础系统安装”">​</a></h3><p>Node 在 Linux，Macintosh，Solaris 这几个系统上都可以完美的运行，linux 的发行版本当中使用 Ubuntu 相当适合。这也是我们为什么要尝试在 ubuntu 15.04 上安装 Node.js，当然了在 14.04 上也可以使用相同的步骤安装。</p><h4 id="_1-系统资源" tabindex="-1">1) 系统资源 <a class="header-anchor" href="#_1-系统资源" aria-label="Permalink to “1) 系统资源”">​</a></h4><p>Node.js 所需的基本的系统资源取决于你的架构需要。本教程我们会在一台 1GB 内存、 1GHz 处理器和 10GB 磁盘空间的服务器上进行，最小安装即可，不需要安装 Web 服务器或数据库服务器。</p><h4 id="_2-系统更新" tabindex="-1">2) 系统更新 <a class="header-anchor" href="#_2-系统更新" aria-label="Permalink to “2) 系统更新”">​</a></h4><p>在我们安装 Node.js 之前，推荐你将系统更新到最新的补丁和升级包，所以请登录到系统中使用超级用户运行如下命令：</p><pre><code># apt-get update
</code></pre><h4 id="_3-安装依赖" tabindex="-1">3) 安装依赖 <a class="header-anchor" href="#_3-安装依赖" aria-label="Permalink to “3) 安装依赖”">​</a></h4><p>Node.js 仅需要你的服务器上有一些基本系统和软件功能，比如 &#39;make&#39;、&#39;gcc&#39;和&#39;wget&#39; 之类的。如果你还没有安装它们，运行如下命令安装：</p><pre><code># apt-get install python gcc make g++ wget
</code></pre><h3 id="下载最新版的node-js-v4-0-0" tabindex="-1">下载最新版的Node JS v4.0.0 <a class="header-anchor" href="#下载最新版的node-js-v4-0-0" aria-label="Permalink to “下载最新版的Node JS v4.0.0”">​</a></h3>`,15)),a("p",null,[e[1]||(e[1]=o("访问链接 ",-1)),n(t,{href:"https://nodejs.org/download/rc/v4.0.0-rc.1/"},{default:d(()=>[...e[0]||(e[0]=[o("Node JS Download Page",-1)])]),_:1}),e[2]||(e[2]=o(" 下载源代码.",-1))]),e[17]||(e[17]=r(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/download.png" alt="nodejs download"></p><p>复制其中的最新的源代码的链接，然后用<code>wget</code> 下载，命令如下：</p><pre><code># wget https://nodejs.org/download/rc/v4.0.0-rc.1/node-v4.0.0-rc.1.tar.gz
</code></pre><p>下载完成后使用命令<code>tar</code> 解压缩：</p><pre><code># tar -zxvf node-v4.0.0-rc.1.tar.gz
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/wget.png" alt="wget nodejs"></p><h3 id="安装-node-js-v4-0-0" tabindex="-1">安装 Node JS v4.0.0 <a class="header-anchor" href="#安装-node-js-v4-0-0" aria-label="Permalink to “安装 Node JS v4.0.0”">​</a></h3><p>现在可以开始使用下载好的源代码编译 Node.js。在开始编译前，你需要在 ubuntu server 上切换到源代码解压缩后的目录，运行 configure 脚本来配置源代码。</p><pre><code>root@ubuntu-15:~/node-v4.0.0-rc.1# ./configure
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/configure.png" alt="Installing NodeJS"></p><p>现在运行命令 &#39;make install&#39; 编译安装 Node.js：</p><pre><code>root@ubuntu-15:~/node-v4.0.0-rc.1# make install
</code></pre><p>make 命令会花费几分钟完成编译，安静的等待一会。</p><h3 id="验证-node-js-安装" tabindex="-1">验证 Node.js 安装 <a class="header-anchor" href="#验证-node-js-安装" aria-label="Permalink to “验证 Node.js 安装”">​</a></h3><p>一旦编译任务完成，我们就可以开始验证安装工作是否 OK。我们运行下列命令来确认 Node.js 的版本。</p><pre><code>root@ubuntu-15:~# node -v
v4.0.0-pre
</code></pre><p>在命令行下不带参数的运行<code>node</code> 就会进入 REPL(Read-Eval-Print-Loop,读-执行-输出-循环)模式，它有一个简化版的emacs 行编辑器，通过它你可以交互式的运行JS和查看运行结果。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/node.png" alt="node version"></p><h3 id="编写测试程序" tabindex="-1">编写测试程序 <a class="header-anchor" href="#编写测试程序" aria-label="Permalink to “编写测试程序”">​</a></h3><p>我们也可以写一个很简单的终端程序来测试安装是否成功，并且工作正常。要做这个，我们将会创建一个“test.js” 文件，包含以下代码，操作如下：</p><pre><code>root@ubuntu-15:~# vim test.js
var util = require(&quot;util&quot;);
console.log(&quot;Hello! This is a Node Test Program&quot;);
:wq!
</code></pre><p>现在为了运行上面的程序，在命令行运行下面的命令。</p><pre><code>root@ubuntu-15:~# node test.js
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/node-test.png" alt="Node Program"></p><p>在一个成功安装了 Node JS 的环境下运行上面的程序就会在屏幕上得到上图所示的输出，这个程序加载类 “util” 到变量 “util” 中，接着用对象 “util” 运行终端任务，console.log 这个命令作用类似 C++ 里的cout</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>就是这些了。如果你刚刚开始使用 Node.js 开发应用程序，希望本文能够通过在 ubuntu 上安装、运行 Node.js 让你了解一下Node.js 的大概。最后，我们可以认为我们可以期待 Node JS v4.0.0 能够取得显著性能提升。</p><hr>`,28)),a("p",null,[e[4]||(e[4]=o("via: ",-1)),n(t,{href:"http://linoxide.com/ubuntu-how-to/setup-node-js-4-0-ubuntu-14-04-15-04/"},{default:d(()=>[...e[3]||(e[3]=[o("http://linoxide.com/ubuntu-how-to/setup-node-js-4-0-ubuntu-14-04-15-04/",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=o("作者：",-1)),n(t,{href:"http://linoxide.com/author/kashifs/"},{default:d(()=>[...e[5]||(e[5]=[o("Kashif Siddique",-1)])]),_:1}),e[9]||(e[9]=o(" 译者：",-1)),n(t,{href:"https://github.com/osk874"},{default:d(()=>[...e[6]||(e[6]=[o("osk874",-1)])]),_:1}),e[10]||(e[10]=o(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:d(()=>[...e[7]||(e[7]=[o("wxy",-1)])]),_:1})]),a("p",null,[e[13]||(e[13]=o("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[11]||(e[11]=[o("LCTT",-1)])]),_:1}),e[14]||(e[14]=o(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:d(()=>[...e[12]||(e[12]=[o("Linux中国",-1)])]),_:1}),e[15]||(e[15]=o(" 荣誉推出",-1))])])}const j=s(i,[["render",b]]);export{S as __pageData,j as default};
